create function extensions.digest(bytea,text) returns bytea language sql immutable as $$select sha256($1)$$;
create function auth.role() returns text language sql as $$ select coalesce(nullif(current_setting('test.role',true),''),'service_role') $$;
create function auth.uid() returns uuid language sql as $$select null::uuid$$;
create function internal_academic.rejected_fee_sha256(text) returns text language sql immutable as $$select encode(sha256(convert_to($1,'UTF8')),'hex')$$;
create function internal_financial_correction.has_payment_evidence(r public.contas_receber) returns boolean language sql as $$select r.data_pagamento is not null or r.valor_pago is not null$$;
create function internal_academic.manual_cycle_manager_first_post_allowed(uuid,uuid) returns boolean language sql as $$select true$$;
create function internal_academic.is_technical_manual_cycle_protected(uuid) returns boolean language sql as $$select false$$;
create function internal_academic.manual_cycle_manager_receivable_valid(uuid,uuid) returns boolean language sql as $$select true$$;
create function public.registrar_turma_financeiro_auditoria(uuid,text,jsonb,text) returns void language sql as $$insert into public.historico_turma_financeira(matricula_id,evento,regra,created_at) values($1,$2,$3,clock_timestamp())$$;
create function public.get_banese_reconciliation_worker_secret() returns text language sql as $$select repeat('x',32)$$;
create function net.http_post(url text,body jsonb,params jsonb,headers jsonb,timeout_milliseconds integer) returns bigint language sql as $$select 1::bigint$$;

